10: /// Check whether an address is canonical for a sign-extended virtual width.
11: ///
12: /// Widths outside `1..=64` are rejected. A 64-bit width accepts every address.
13: pub const fn is_canonical_virtual_address(address: u64, address_bits: u8) -> bool {
14:     if address_bits == 0 || address_bits > 64 {
15:         return false;
16:     }
17:     if address_bits == 64 {
18:         return true;
19:     }
20: 
21:     let sign_bit = (address >> (address_bits - 1)) & 1;
22:     let upper_bits = address >> address_bits;
23:     let expected_upper_bits = if sign_bit == 0 {
24:         0
25:     } else {
26:         u64::MAX >> address_bits
27:     };
28:     upper_bits == expected_upper_bits
29: }
