31: /// Check that a non-empty half-open physical range fits an address width.
32: pub const fn physical_range_fits_address_width(start: u64, end: u64, address_bits: u8) -> bool {
33:     if start >= end || address_bits == 0 || address_bits > 64 {
34:         return false;
35:     }
36:     address_bits == 64 || end <= (1u64 << address_bits)
37: }
