45:     physical_base: u64,
46:     reported_virtual_base: u64,
47:     linked_virtual_start: u64,
48:     linked_virtual_end: u64,
49:     physical_bits: Option<u8>,
50:     virtual_bits: u8,
51: ) -> Option<u64> {
52:     if linked_virtual_start != reported_virtual_base
53:         || linked_virtual_start >= linked_virtual_end
54:         || physical_base & 0xfff != 0
55:         || linked_virtual_start & 0xfff != 0
56:     {
57:         return None;
58:     }
59: 
60:     let virtual_last = linked_virtual_end - 1;
61:     if !is_canonical_virtual_address(linked_virtual_start, virtual_bits)
62:         || !is_canonical_virtual_address(virtual_last, virtual_bits)
63:     {
64:         return None;
65:     }
66:     let sign_bit = 1u64 << (virtual_bits - 1);
67:     if linked_virtual_start & sign_bit != virtual_last & sign_bit {
68:         return None;
