224: /// Derive the requested initial x86_64 stack span below Limine's entry RSP.
225: ///
226: /// The SysV entry stack has an 8-byte return-address slot, so `entry_rsp + 8`
227: /// is the exclusive top. The requested span must be at least the protocol's
228: /// 64 KiB minimum; callers should pass the size actually requested from Limine.
229: pub const fn limine_x86_64_stack_bounds(
230:     entry_rsp: u64,
231:     virtual_bits: u8,
232:     stack_size: u64,
233: ) -> Option<(u64, u64)> {
234:     if entry_rsp & 0xf != 8 {
235:         return None;
236:     }
237:     let Some(stack_end) = entry_rsp.checked_add(8) else {
238:         return None;
239:     };
240:     if stack_size < LIMINE_X86_64_MIN_STACK_SIZE {
241:         return None;
242:     }
243:     let Some(stack_start) = stack_end.checked_sub(stack_size) else {
244:         return None;
245:     };
246:     let stack_last = stack_end - 1;
247:     if !is_canonical_virtual_address(stack_start, virtual_bits)
248:         || !is_canonical_virtual_address(stack_last, virtual_bits)
249:     {
250:         return None;
251:     }
252:     let sign_bit = 1u64 << (virtual_bits - 1);
253:     if stack_start & sign_bit != stack_last & sign_bit {
254:         return None;
255:     }
256:     Some((stack_start, stack_end))
257: }
