287:     let mapped_start = physical_start & PAGE_MASK;
288:     let Some(rounded_end) = physical_end.checked_add(PAGE_SIZE - 1) else {
289:         return false;
290:     };
291:     let mapped_end = rounded_end & PAGE_MASK;
292:     if mapped_start >= mapped_end {
293:         return false;
294:     }
295:     if let Some(bits) = physical_bits {
296:         if !physical_range_fits_address_width(mapped_start, mapped_end, bits) {
