455:     pub const fn mapping_start(self) -> u64 {
456:         self.mapping_start
457:     }
458: 
459:     pub const fn mapping_end(self) -> u64 {
460:         self.mapping_end
461:     }
462: 
463:     /// Whether one aligned 4 KiB physical page is fully covered by this span's
464:     /// validated page-rounded mapping extent.
465:     pub fn contains_mapping_page(self, physical_page: u64) -> bool {
466:         if physical_page & 0xfff != 0 {
467:             return false;
468:         }
469:         let Some(page_end) = physical_page.checked_add(4096) else {
470:             return false;
471:         };
472:         let authorization_contains_page = match self.authorization {
473:             AcpiSpanAuthorization::AcpiTableMemory => true,
474:             AcpiSpanAuthorization::LegacyRsdpReserved => {
475:                 physical_page >= 0x80_000 && page_end <= 0x10_0000
476:             }
477:         };
478:         authorization_contains_page
479:             && physical_page >= self.mapping_start
480:             && page_end <= self.mapping_end
481:     }
482: }
