484: /// Validated, allocation-free snapshot of the physical memory map.
485: #[derive(Debug, PartialEq, Eq)]
486: pub struct MemoryMap {
487:     regions: [PhysicalRegion; MAX_MEMORY_REGIONS],
488:     region_count: usize,
489:     usable_bytes: u64,
490: }
491: 
492: impl MemoryMap {
493:     const EMPTY: Self = Self {
494:         regions: [PhysicalRegion::EMPTY; MAX_MEMORY_REGIONS],
495:         region_count: 0,
496:         usable_bytes: 0,
497:     };
498: 
499:     pub fn from_raw(regions: &[RawMemoryRegion]) -> Result<Self, MemoryMapError> {
500:         let mut builder = MemoryMapBuilder::new();
501:         for region in regions {
502:             builder.push(region.base, region.length, region.kind)?;
503:         }
504:         builder.finish()
505:     }
506: 
507:     pub fn regions(&self) -> &[PhysicalRegion] {
508:         &self.regions[..self.region_count]
509:     }
510: 
511:     pub fn range_is_within_region_kind(&self, start: u64, end: u64, kind: RegionKind) -> bool {
512:         start < end
513:             && self
514:                 .regions()
515:                 .iter()
516:                 .any(|region| region.start <= start && end <= region.end && region.kind == kind)
517:     }
518: 
519:     /// Check that a non-empty physical span is covered only by ACPI reclaimable
520:     /// or ACPI NVS regions, optionally enforcing the reported physical width.
521:     /// Adjacent ACPI regions may jointly cover the span; gaps and other region
522:     /// kinds are rejected. This checks metadata only and does not authorize a
523:     /// dereference or imply that the span is mapped.
524:     pub fn validate_acpi_span(
525:         &self,
526:         start: u64,
527:         length: u64,
528:         physical_address_bits: Option<u8>,
529:     ) -> Result<ValidatedAcpiSpan, AcpiSpanError> {
530:         const PAGE_SIZE: u64 = 4096;
531:         const MAX_SPAN_SIZE: u64 = 64 * 1024;
532: 
533:         if length == 0 {
534:             return Err(AcpiSpanError::EmptyRange);
535:         }
536:         if length > MAX_SPAN_SIZE {
537:             return Err(AcpiSpanError::SpanTooLarge);
538:         }
539:         let end = start
540:             .checked_add(length)
541:             .ok_or(AcpiSpanError::AddressOverflow)?;
542:         if physical_address_bits
543:             .is_some_and(|bits| !physical_range_fits_address_width(start, end, bits))
544:         {
545:             return Err(AcpiSpanError::PhysicalRangeOutOfBounds);
546:         }
547:         let mapping_start = start & !(PAGE_SIZE - 1);
548:         let mapping_end = end
549:             .checked_add(PAGE_SIZE - 1)
550:             .ok_or(AcpiSpanError::AddressOverflow)?
551:             & !(PAGE_SIZE - 1);
552:         if mapping_end <= mapping_start {
553:             return Err(AcpiSpanError::AddressOverflow);
554:         }
555:         if physical_address_bits.is_some_and(|bits| {
556:             !physical_range_fits_address_width(mapping_start, mapping_end, bits)
557:         }) {
558:             return Err(AcpiSpanError::PhysicalRangeOutOfBounds);
559:         }
560:         if !self.range_is_within_acpi_regions(mapping_start, mapping_end, physical_address_bits) {
561:             return Err(AcpiSpanError::NotFullyAcpiBacked);
562:         }
563: 
564:         Ok(ValidatedAcpiSpan {
565:             byte_start: start,
566:             byte_end: end,
567:             mapping_start,
568:             mapping_end,
569:             authorization: AcpiSpanAuthorization::AcpiTableMemory,
570:         })
571:     }
572: 
573:     /// Validate an RSDP span in ACPI memory or in the bounded legacy x86
574:     /// firmware window `[0x80000, 0x100000)`. The legacy exception is only for
575:     /// the RSDP itself; table addresses must use `validate_acpi_span`.
576:     pub fn validate_rsdp_span(
577:         &self,
578:         start: u64,
579:         length: u64,
580:         physical_address_bits: Option<u8>,
581:     ) -> Result<ValidatedAcpiSpan, AcpiSpanError> {
582:         if let Ok(span) = self.validate_acpi_span(start, length, physical_address_bits) {
583:             return Ok(span);
584:         }
585:         const PAGE_SIZE: u64 = 4096;
586:         const LEGACY_RSDP_START: u64 = 0x80_000;
587:         const LEGACY_RSDP_END: u64 = 0x10_0000;
588:         const MAX_SPAN_SIZE: u64 = 64 * 1024;
589: 
590:         if length == 0 {
591:             return Err(AcpiSpanError::EmptyRange);
592:         }
593:         if length > MAX_SPAN_SIZE {
594:             return Err(AcpiSpanError::SpanTooLarge);
595:         }
596:         let end = start
597:             .checked_add(length)
598:             .ok_or(AcpiSpanError::AddressOverflow)?;
599:         if physical_address_bits
600:             .is_some_and(|bits| !physical_range_fits_address_width(start, end, bits))
601:         {
602:             return Err(AcpiSpanError::PhysicalRangeOutOfBounds);
603:         }
604:         let mapping_start = start & !(PAGE_SIZE - 1);
605:         let mapping_end = end
606:             .checked_add(PAGE_SIZE - 1)
607:             .ok_or(AcpiSpanError::AddressOverflow)?
608:             & !(PAGE_SIZE - 1);
609:         if mapping_end <= mapping_start {
610:             return Err(AcpiSpanError::AddressOverflow);
611:         }
612:         if mapping_start < LEGACY_RSDP_START
613:             || mapping_end > LEGACY_RSDP_END
614:             || physical_address_bits.is_some_and(|bits| {
615:                 !physical_range_fits_address_width(mapping_start, mapping_end, bits)
616:             })
617:             || !self.range_is_covered_by_kind(mapping_start, mapping_end, RegionKind::Reserved)
618:         {
619:             return Err(AcpiSpanError::NotFullyAcpiBacked);
620:         }
621: 
622:         Ok(ValidatedAcpiSpan {
623:             byte_start: start,
624:             byte_end: end,
625:             mapping_start,
626:             mapping_end,
627:             authorization: AcpiSpanAuthorization::LegacyRsdpReserved,
628:         })
629:     }
630: 
631:     fn range_is_covered_by_kind(&self, start: u64, end: u64, kind: RegionKind) -> bool {
632:         if start >= end {
633:             return false;
634:         }
635:         let mut covered_until = start;
636:         for region in self.regions() {
637:             if region.end <= covered_until {
638:                 continue;
639:             }
640:             if region.start > covered_until || region.kind != kind {
641:                 return false;
642:             }
643:             covered_until = region.end.min(end);
644:             if covered_until == end {
645:                 return true;
646:             }
647:         }
648:         false
649:     }
650: 
651:     pub fn range_is_within_acpi_regions(
652:         &self,
653:         start: u64,
654:         end: u64,
655:         physical_address_bits: Option<u8>,
656:     ) -> bool {
657:         if start >= end
658:             || physical_address_bits
659:                 .is_some_and(|bits| !physical_range_fits_address_width(start, end, bits))
660:         {
661:             return false;
662:         }
663: 
664:         let mut covered_until = start;
665:         for region in self.regions() {
666:             if region.end <= covered_until {
667:                 continue;
668:             }
669:             if region.start > covered_until
670:                 || !matches!(
671:                     region.kind,
672:                     RegionKind::AcpiReclaimable | RegionKind::AcpiNvs
673:                 )
674:             {
675:                 return false;
676:             }
677:             covered_until = region.end.min(end);
678:             if covered_until == end {
679:                 return true;
680:             }
681:         }
682:         false
683:     }
684: 
685:     /// Calculate the Limine base-revision-3 HHDM address of a page-aligned
686:     /// extent wholly contained in one region that Limine maps into the HHDM.
687:     ///
688:     /// This validates metadata and relies on the Limine handoff contract for the
689:     /// actual mapping; it does not inspect inherited page tables or make the
690:     /// returned integer safe to dereference by itself.
691:     pub fn limine_hhdm_address(
692:         &self,
693:         hhdm_offset: u64,
694:         physical_start: u64,
695:         length: u64,
696:         physical_address_bits: Option<u8>,
697:         virtual_address_bits: u8,
698:     ) -> Result<u64, HhdmAddressError> {
699:         const PAGE_SIZE: u64 = 4096;
700: 
701:         let physical_address_bits =
702:             physical_address_bits.ok_or(HhdmAddressError::UnknownPhysicalAddressWidth)?;
703:         if length == 0 {
704:             return Err(HhdmAddressError::EmptyRange);
705:         }
706:         if (physical_start | length) & (PAGE_SIZE - 1) != 0 {
707:             return Err(HhdmAddressError::UnalignedRange);
708:         }
709:         let physical_end = physical_start
710:             .checked_add(length)
711:             .ok_or(HhdmAddressError::AddressOverflow)?;
712:         if !self.regions().iter().any(|region| {
713:             region.start <= physical_start
714:                 && physical_end <= region.end
715:                 && region.kind.is_mapped_by_limine_v3_hhdm()
716:         }) {
717:             return Err(HhdmAddressError::NotLimineMapped);
718:         }
719:         if !limine_v3_hhdm_range_is_valid(
720:             hhdm_offset,
721:             physical_start,
722:             physical_end,
723:             Some(physical_address_bits),
724:             virtual_address_bits,
725:         ) {
726:             return Err(HhdmAddressError::InvalidHhdmRange);
727:         }
728:         hhdm_offset
729:             .checked_add(physical_start)
730:             .ok_or(HhdmAddressError::InvalidHhdmRange)
731:     }
732: 
733:     /// Calculate the HHDM address of a page-aligned extent wholly contained in
734:     /// validated `Usable` memory.
735:     pub fn usable_hhdm_address(
736:         &self,
737:         hhdm_offset: u64,
738:         physical_start: u64,
739:         length: u64,
740:         physical_address_bits: Option<u8>,
741:         virtual_address_bits: u8,
742:     ) -> Result<u64, HhdmAddressError> {
743:         const PAGE_SIZE: u64 = 4096;
744: 
745:         if length == 0 {
746:             return Err(HhdmAddressError::EmptyRange);
747:         }
748:         if (physical_start | length) & (PAGE_SIZE - 1) != 0 {
749:             return Err(HhdmAddressError::UnalignedRange);
750:         }
751:         let physical_end = physical_start
752:             .checked_add(length)
753:             .ok_or(HhdmAddressError::AddressOverflow)?;
754:         if !self.range_is_within_region_kind(physical_start, physical_end, RegionKind::Usable) {
755:             return Err(HhdmAddressError::NotUsable);
756:         }
757:         self.limine_hhdm_address(
758:             hhdm_offset,
759:             physical_start,
760:             length,
761:             physical_address_bits,
762:             virtual_address_bits,
763:         )
764:     }
765: 
766:     pub const fn usable_bytes(&self) -> u64 {
767:         self.usable_bytes
768:     }
769: }
