180: /// Owned snapshot of bootloader data and CPU state consumed by the kernel.
181: pub struct BootInfo {
182:     pub hhdm_revision: u64,
183:     pub hhdm_offset: u64,
184:     pub inherited_cr3_raw: u64,
185:     pub inherited_cr3_root: Result<Cr3Root, Cr3Error>,
186:     pub executable_address_revision: u64,
187:     pub kernel_physical_base: u64,
188:     pub kernel_physical_end: u64,
189:     pub kernel_virtual_base: u64,
190:     pub kernel_virtual_end: u64,
191:     pub kernel_image_segments: KernelImageSegments,
192:     pub boot_stack_physical_start: u64,
193:     pub boot_stack_physical_end: u64,
194:     pub boot_stack_virtual_start: u64,
195:     pub boot_stack_virtual_end: u64,
196:     pub memory_map_revision: u64,
197:     /// Limine base-revision-3 physical address of the RSDP, if ACPI is present.
198:     /// The address is metadata only; no ACPI bytes are dereferenced during boot capture.
199:     pub rsdp_physical_address: Option<u64>,
200:     /// Copied xAPIC topology used by the later interrupt-controller setup.
201:     pub acpi_madt: Option<rustix_kernel::acpi::Madt>,
202:     pub memory_map: MemoryMap,
203:     pub frame_allocator: FrameAllocator,
204:     pub cpu_info: crate::arch::x86_64::cpu::CpuInfo,
205: }
