207: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
208: pub enum BootInfoError {
209:     UnsupportedBaseRevision { reported: u64, required: u64 },
210:     MissingHhdmResponse,
211:     InvalidHhdmResponsePointer,
212:     InvalidHhdmOffset,
213:     MissingExecutableAddressResponse,
214:     InvalidExecutableAddressResponsePointer,
215:     InvalidKernelImageRange,
216:     InvalidKernelImageSegments,
217:     MissingStackSizeResponse,
218:     InvalidStackSizeResponsePointer,
219:     InvalidInitialStackBounds,
220:     InvalidInitialStackHhdmRange,
221:     InitialStackNotBootloaderReclaimable,
222:     MissingMemoryMapResponse,
223:     InvalidMemoryMapResponsePointer,
224:     MemoryMapCountDoesNotFit,
225:     TooManyMemoryRegions,
226:     EmptyMemoryMap,
227:     InvalidEntriesPointer,
228:     InvalidRsdpResponsePointer,
229:     InvalidRsdpAddress,
230:     InvalidRsdpMappingSpan,
231:     EntriesAddressOverflow,
232:     InvalidEntryPointer { index: usize },
233:     InvalidPhysicalRange { index: usize },
234:     InvalidHhdmMappingRange { index: usize },
235:     InvalidMemoryMap(MemoryMapError),
236:     FrameAllocator(FrameError),
237: }
238: 
239: /// Copy and validate the boot data needed by the current kernel.
240: ///
241: /// Structural checks can reject malformed pointers and ranges, but cannot prove
242: /// that a loader-provided pointer is mapped and readable. That remains part of
243: /// the documented Limine handoff trust boundary until the kernel owns its maps.
244: pub fn capture_boot_information(entry_rsp: u64) -> Result<BootInfo, BootInfoError> {
245:     let base_revision_request = core::ptr::addr_of_mut!(BASE_REVISION_REQUEST);
246:     // SAFETY: Limine updates the writable base-revision request before entering
247:     // the kernel. A volatile read observes the loader's support result.
248:     let revision_pointer = base_revision_request.cast::<u64>().wrapping_add(2);
249:     let reported_base_revision = unsafe { core::ptr::read_volatile(revision_pointer) };
250:     if reported_base_revision != 0 {
251:         return Err(BootInfoError::UnsupportedBaseRevision {
252:             reported: reported_base_revision,
253:             required: REQUIRED_BASE_REVISION,
254:         });
255:     }
256: 
257:     let cpu_info = crate::arch::x86_64::cpu::identify();
258:     let inherited_cr3_raw = crate::arch::x86_64::cpu::read_cr3_raw();
259:     let inherited_cr3_root = parse_cr3_root(
260:         inherited_cr3_raw,
261:         cpu_info.physical_address_bits,
262:         cpu_info.pcid_enabled,
263:     );
264:     let virtual_address_bits = cpu_info.active_linear_address_bits;
265:     let stack_size_request = core::ptr::addr_of_mut!(STACK_SIZE_REQUEST);
266:     // SAFETY: Limine completes supported request responses before `_start`.
267:     let stack_size_response_pointer =
268:         unsafe { core::ptr::read_volatile(core::ptr::addr_of!((*stack_size_request).response)) };
269:     if stack_size_response_pointer.is_null() {
270:         return Err(BootInfoError::MissingStackSizeResponse);
271:     }
272:     if !is_valid_pointer(stack_size_response_pointer, virtual_address_bits) {
273:         return Err(BootInfoError::InvalidStackSizeResponsePointer);
274:     }
275:     // SAFETY: The response pointer is non-null, aligned, and canonical. As with
276:     // the other Limine responses, readability relies on the handoff contract.
277:     let _stack_size_response = unsafe { stack_size_response_pointer.read_volatile() };
278:     let (boot_stack_virtual_start, boot_stack_virtual_end) =
279:         limine_x86_64_stack_bounds(entry_rsp, virtual_address_bits, REQUESTED_BOOT_STACK_SIZE)
280:             .ok_or(BootInfoError::InvalidInitialStackBounds)?;
281:     let hhdm_request = core::ptr::addr_of_mut!(HHDM_REQUEST);
282:     // SAFETY: Limine has completed writing the request response before `_start`.
283:     let hhdm_pointer =
284:         unsafe { core::ptr::read_volatile(core::ptr::addr_of!((*hhdm_request).response)) };
285:     if hhdm_pointer.is_null() {
286:         return Err(BootInfoError::MissingHhdmResponse);
287:     }
288:     if !is_valid_pointer(hhdm_pointer, virtual_address_bits) {
289:         return Err(BootInfoError::InvalidHhdmResponsePointer);
290:     }
291:     // SAFETY: The Limine response pointer is trusted to refer to a readable
292:     // response object; its nullness and alignment are checked above.
293:     let hhdm = unsafe { hhdm_pointer.read_volatile() };
294:     if hhdm.offset & 0xfff != 0 || !is_canonical_virtual_address(hhdm.offset, virtual_address_bits)
295:     {
296:         return Err(BootInfoError::InvalidHhdmOffset);
297:     }
298: 
299:     let executable_address_request = core::ptr::addr_of_mut!(EXECUTABLE_ADDRESS_REQUEST);
300:     // SAFETY: Limine has completed writing the request response before `_start`.
301:     let executable_address_pointer = unsafe {
302:         core::ptr::read_volatile(core::ptr::addr_of!((*executable_address_request).response))
303:     };
304:     if executable_address_pointer.is_null() {
305:         return Err(BootInfoError::MissingExecutableAddressResponse);
306:     }
307:     if !is_valid_pointer(executable_address_pointer, virtual_address_bits) {
308:         return Err(BootInfoError::InvalidExecutableAddressResponsePointer);
309:     }
310:     // SAFETY: Limine's response pointer is trusted to refer to a readable object;
311:     // nullness, alignment, and active-width canonicality were checked above.
312:     let executable_address = unsafe { executable_address_pointer.read_volatile() };
313:     // `linker.ld` defines these symbols as the boundaries of the loaded image.
314:     let (linked_virtual_start, linked_virtual_end) = (
315:         core::ptr::addr_of!(__kernel_start) as u64,
316:         core::ptr::addr_of!(__kernel_end) as u64,
317:     );
318:     let kernel_physical_end = kernel_image_physical_end(
319:         executable_address.physical_base,
320:         executable_address.virtual_base,
321:         linked_virtual_start,
322:         linked_virtual_end,
323:         cpu_info.physical_address_bits,
324:         virtual_address_bits,
325:     )
326:     .ok_or(BootInfoError::InvalidKernelImageRange)?;
327:     let linked_segments = KernelImageVirtualSegments {
328:         text: (
329:             core::ptr::addr_of!(__kernel_text_mapping_start) as u64,
330:             core::ptr::addr_of!(__kernel_text_mapping_end) as u64,
331:         ),
332:         rodata: (
333:             core::ptr::addr_of!(__kernel_rodata_mapping_start) as u64,
334:             core::ptr::addr_of!(__kernel_rodata_mapping_end) as u64,
335:         ),
336:         data: (
337:             core::ptr::addr_of!(__kernel_data_mapping_start) as u64,
338:             core::ptr::addr_of!(__kernel_data_mapping_end) as u64,
339:         ),
340:     };
341:     let kernel_image_segments = kernel_image_segments(
342:         executable_address.physical_base,
343:         executable_address.virtual_base,
344:         linked_virtual_start,
345:         linked_virtual_end,
346:         linked_segments,
347:         cpu_info.physical_address_bits,
348:         virtual_address_bits,
349:     )
350:     .ok_or(BootInfoError::InvalidKernelImageSegments)?;
351: 
352:     let memory_map_request = core::ptr::addr_of_mut!(MEMORY_MAP_REQUEST);
353:     // SAFETY: Limine has completed writing the request response before `_start`.
354:     let memory_map_pointer =
355:         unsafe { core::ptr::read_volatile(core::ptr::addr_of!((*memory_map_request).response)) };
356:     if memory_map_pointer.is_null() {
357:         return Err(BootInfoError::MissingMemoryMapResponse);
358:     }
359:     if !is_valid_pointer(memory_map_pointer, virtual_address_bits) {
360:         return Err(BootInfoError::InvalidMemoryMapResponsePointer);
361:     }
362:     // SAFETY: The Limine response pointer is trusted to refer to a readable
363:     // response object; its nullness and alignment are checked above.
364:     let response = unsafe { memory_map_pointer.read_volatile() };
365:     let entry_count = usize::try_from(response.entry_count)
366:         .map_err(|_| BootInfoError::MemoryMapCountDoesNotFit)?;
367:     if entry_count > MAX_MEMORY_REGIONS {
368:         return Err(BootInfoError::TooManyMemoryRegions);
369:     }
370:     if entry_count == 0 {
371:         return Err(BootInfoError::EmptyMemoryMap);
372:     }
373:     if response.entries.is_null() {
374:         return Err(BootInfoError::InvalidEntriesPointer);
375:     }
376:     if !is_valid_pointer(response.entries, virtual_address_bits) {
377:         return Err(BootInfoError::InvalidEntriesPointer);
378:     }
379:     let entry_bytes = entry_count
380:         .checked_mul(size_of::<*const MemoryMapEntry>())
381:         .ok_or(BootInfoError::EntriesAddressOverflow)?;
382:     let entries_start = response.entries as usize;
383:     let entries_end = entries_start
384:         .checked_add(entry_bytes)
385:         .ok_or(BootInfoError::EntriesAddressOverflow)?;
386:     if !is_canonical_virtual_address(entries_start as u64, virtual_address_bits)
387:         || !is_canonical_virtual_address((entries_end - 1) as u64, virtual_address_bits)
388:     {
389:         return Err(BootInfoError::InvalidEntriesPointer);
390:     }
391: 
392:     let mut builder = MemoryMapBuilder::new();
393:     for index in 0..entry_count {
394:         // SAFETY: Limine promises an array of `entry_count` pointers. The count
395:         // is capped and pointer alignment/address arithmetic are checked above.
396:         let entry_pointer = unsafe { response.entries.add(index).read_volatile() };
397:         if !is_valid_pointer(entry_pointer, virtual_address_bits) {
398:             return Err(BootInfoError::InvalidEntryPointer { index });
399:         }
400:         // SAFETY: Limine promises each non-null entry pointer is readable.
401:         let entry = unsafe { entry_pointer.read_volatile() };
402:         builder
403:             .push(entry.base, entry.length, entry.kind)
404:             .map_err(BootInfoError::InvalidMemoryMap)?;
405:     }
406: 
407:     let memory_map = builder.finish().map_err(|error| match error {
408:         MemoryMapError::EmptyMap => BootInfoError::EmptyMemoryMap,
409:         other => BootInfoError::InvalidMemoryMap(other),
410:     })?;
411:     for (index, region) in memory_map.regions().iter().enumerate() {
412:         if let Some(physical_bits) = cpu_info.physical_address_bits {
413:             if !physical_range_fits_address_width(region.start(), region.end(), physical_bits) {
414:                 return Err(BootInfoError::InvalidPhysicalRange { index });
415:             }
416:         }
417:         if region.kind().is_mapped_by_limine_v3_hhdm()
418:             && !limine_v3_hhdm_range_is_valid(
419:                 hhdm.offset,
420:                 region.start(),
421:                 region.end(),
422:                 cpu_info.physical_address_bits,
423:                 virtual_address_bits,
424:             )
425:         {
426:             return Err(BootInfoError::InvalidHhdmMappingRange { index });
427:         }
428:     }
429:     let boot_stack_physical_start = boot_stack_virtual_start
430:         .checked_sub(hhdm.offset)
431:         .ok_or(BootInfoError::InvalidInitialStackHhdmRange)?;
432:     let boot_stack_physical_end = boot_stack_virtual_end
433:         .checked_sub(hhdm.offset)
434:         .ok_or(BootInfoError::InvalidInitialStackHhdmRange)?;
435:     if !limine_v3_hhdm_range_is_valid(
436:         hhdm.offset,
437:         boot_stack_physical_start,
438:         boot_stack_physical_end,
439:         cpu_info.physical_address_bits,
440:         virtual_address_bits,
441:     ) {
442:         return Err(BootInfoError::InvalidInitialStackHhdmRange);
443:     }
444:     if !memory_map.range_is_within_region_kind(
445:         boot_stack_physical_start,
446:         boot_stack_physical_end,
447:         RegionKind::BootloaderReclaimable,
448:     ) {
449:         return Err(BootInfoError::InitialStackNotBootloaderReclaimable);
450:     }
451:     let rsdp_request = core::ptr::addr_of_mut!(RSDP_REQUEST);
452:     // SAFETY: Limine completes supported request responses before `_start`.
453:     let rsdp_response_pointer =
454:         unsafe { core::ptr::read_volatile(core::ptr::addr_of!((*rsdp_request).response)) };
455:     let rsdp_physical_address = if rsdp_response_pointer.is_null() {
456:         None
457:     } else {
458:         if !is_valid_pointer(rsdp_response_pointer, virtual_address_bits) {
459:             return Err(BootInfoError::InvalidRsdpResponsePointer);
460:         }
461:         // SAFETY: Limine's response pointer is non-null, aligned, and canonical.
462:         // As for the other boot responses, readability relies on the handoff contract.
463:         let response = unsafe { rsdp_response_pointer.read_volatile() };
464:         if response.address.is_null() {
465:             return Err(BootInfoError::InvalidRsdpAddress);
466:         }
467:         let address = response.address as u64;
468:         if let Err(error) =
469:             memory_map.validate_rsdp_span(address, 20, cpu_info.physical_address_bits)
470:         {
471:             crate::kprintln!("RSDP physical span {:#x} rejected: {:?}", address, error);
472:             let page_start = address & !0xfff;
473:             let page_end = page_start.checked_add(4096);
474:             if let Some(page_end) = page_end {
475:                 for region in memory_map.regions() {
476:                     if region.start() < page_end && page_start < region.end() {
477:                         crate::kprintln!(
478:                             "RSDP page intersects {:#x}..{:#x} ({:?})",
479:                             region.start(),
480:                             region.end(),
481:                             region.kind()
482:                         );
483:                     }
484:                 }
485:             }
486:             return Err(BootInfoError::InvalidRsdpMappingSpan);
487:         }
488:         Some(address)
489:     };
490: 
491:     let frame_allocator =
492:         FrameAllocator::from_memory_map(&memory_map).map_err(BootInfoError::FrameAllocator)?;
493: 
494:     Ok(BootInfo {
495:         hhdm_revision: hhdm.revision,
496:         hhdm_offset: hhdm.offset,
497:         inherited_cr3_raw,
498:         inherited_cr3_root,
499:         executable_address_revision: executable_address.revision,
500:         kernel_physical_base: executable_address.physical_base,
501:         kernel_physical_end,
502:         kernel_virtual_base: executable_address.virtual_base,
503:         kernel_virtual_end: linked_virtual_end,
504:         kernel_image_segments,
505:         boot_stack_physical_start,
506:         boot_stack_physical_end,
507:         boot_stack_virtual_start,
508:         boot_stack_virtual_end,
509:         memory_map_revision: response.revision,
510:         rsdp_physical_address,
511:         acpi_madt: None,
512:         memory_map,
513:         frame_allocator,
514:         cpu_info,
515:     })
516: }
517: 
518: /// Print a report from the copied snapshot; no loader pointers are used here.
519: pub fn report_boot_information(boot_info: &BootInfo) {
520:     crate::kprintln!(
521:         "HHDM: offset {:#018x}, response revision {}",
522:         boot_info.hhdm_offset,
523:         boot_info.hhdm_revision
524:     );
525:     crate::kprintln!(
526:         "inherited CR3: raw {:#018x} (not walked during boot snapshot)",
527:         boot_info.inherited_cr3_raw
528:     );
529:     match boot_info.inherited_cr3_root {
530:         Ok(root) => crate::kprintln!(
531:             "inherited CR3 root: physical {:#018x}, low bits {:?}",
532:             root.physical_address(),
533:             root.low_bits()
534:         ),
535:         Err(error) => crate::kprintln!("inherited CR3 root could not be decoded: {:?}", error),
536:     }
537:     crate::kprintln!(
538:         "kernel image: physical [{:#018x}, {:#018x}), virtual [{:#018x}, {:#018x}), response revision {}",
539:         boot_info.kernel_physical_base,
540:         boot_info.kernel_physical_end,
541:         boot_info.kernel_virtual_base,
542:         boot_info.kernel_virtual_end,
543:         boot_info.executable_address_revision
544:     );
545:     let segments = &boot_info.kernel_image_segments;
546:     crate::kprintln!(
547:         "kernel mapping text RX: physical [{:#018x}, {:#018x}), virtual [{:#018x}, {:#018x})",
548:         segments.text.physical_start,
549:         segments.text.physical_end,
550:         segments.text.virtual_start,
551:         segments.text.virtual_end
552:     );
553:     crate::kprintln!(
554:         "kernel mapping rodata R/NX: physical [{:#018x}, {:#018x}), virtual [{:#018x}, {:#018x})",
555:         segments.rodata.physical_start,
556:         segments.rodata.physical_end,
557:         segments.rodata.virtual_start,
558:         segments.rodata.virtual_end
559:     );
560:     crate::kprintln!(
561:         "kernel mapping data RW/NX: physical [{:#018x}, {:#018x}), virtual [{:#018x}, {:#018x})",
562:         segments.data.physical_start,
563:         segments.data.physical_end,
564:         segments.data.virtual_start,
565:         segments.data.virtual_end
566:     );
567:     crate::kprintln!(
568:         "boot stack (requested span: {} KiB): physical [{:#018x}, {:#018x}), virtual [{:#018x}, {:#018x})",
569:         (boot_info.boot_stack_virtual_end - boot_info.boot_stack_virtual_start) / 1024,
570:         boot_info.boot_stack_physical_start,
571:         boot_info.boot_stack_physical_end,
572:         boot_info.boot_stack_virtual_start,
573:         boot_info.boot_stack_virtual_end
574:     );
575:     crate::kprintln!(
576:         "memory map: {} validated regions, {} MiB usable RAM, response revision {}",
577:         boot_info.memory_map.regions().len(),
578:         boot_info.memory_map.usable_bytes() / (1024 * 1024),
579:         boot_info.memory_map_revision
580:     );
581:     match boot_info.rsdp_physical_address {
582:         Some(address) => crate::kprintln!(
583:             "ACPI RSDP: physical {:#018x} (initial 20-byte span validated; not dereferenced)",
584:             address
585:         ),
586:         None => crate::kprintln!("ACPI RSDP: unavailable"),
587:     }
588:     crate::kprintln!(
589:         "physical frames: {} managed, {} free (4 KiB each)",
590:         boot_info.frame_allocator.managed_frames(),
591:         boot_info.frame_allocator.free_frames()
592:     );
593:     for region in boot_info.memory_map.regions() {
594:         crate::kprintln!(
595:             "  [{:#018x}, {:#018x}) {:?}",
596:             region.start(),
597:             region.end(),
598:             region.kind()
599:         );
600:     }
601:     crate::kprintln!("console: COM1 serial (polling)");
602: 
603:     let cpu = &boot_info.cpu_info;
604:     let vendor = core::str::from_utf8(&cpu.vendor).unwrap_or("unknown");
605:     let mtrr_supported = !matches!(&cpu.mtrr, MtrrState::Unsupported);
606:     crate::kprintln!(
607:         "CPU: {} (basic leaf {}, extended leaf {:#x})",
608:         vendor,
609:         cpu.max_basic_leaf,
610:         cpu.max_extended_leaf
611:     );
612:     crate::kprintln!(
613:         "CPU feature support: SSE2={}, NX={}, NXE-enabled={}, normal-caching={}, PAT={}, MTRR={}, 1GiB-pages={}, long-mode={}, LA57-supported={}, PCID-enabled={}",
614:         cpu.has_sse2,
615:         cpu.has_nx,
616:         cpu.nx_enabled,
617:         cpu.normal_caching,
618:         cpu.has_pat,
619:         mtrr_supported,
620:         cpu.has_1g_pages,
621:         cpu.has_long_mode,
622:         cpu.has_la57,
623:         cpu.pcid_enabled
624:     );
625:     match cpu.pat_msr_value {
626:         Some(value) => match PatLayout::from_msr_value(value) {
627:             Ok(layout) => crate::kprintln!(
628:                 "PAT: IA32_PAT={:#018x}, WB index={:?}, UC index={:?}, WC index={:?}",
629:                 value,
630:                 layout.index_for(CachePolicy::WriteBack),
631:                 layout.index_for(CachePolicy::Uncacheable),
632:                 layout.index_for(CachePolicy::WriteCombining)
633:             ),
634:             Err(error) => crate::kprintln!(
635:                 "PAT: IA32_PAT={:#018x} has unsupported layout: {:?}",
636:                 value,
637:                 error
638:             ),
639:         },
640:         None => crate::kprintln!("PAT: unsupported"),
641:     }
642:     match &cpu.mtrr {
643:         MtrrState::Unsupported => {
644:             crate::kprintln!("MTRR: unsupported")
645:         }
646:         MtrrState::VariableRangeCapacityExceeded { reported_count } => {
647:             crate::kprintln!(
648:                 "MTRR: {} variable pairs exceed the snapshot capacity {}; no partial state retained",
649:                 reported_count,
650:                 MAX_CAPTURED_VARIABLE_MTRRS
651:             )
652:         }
653:         MtrrState::Captured(registers) => {
654:             crate::kprintln!(
655:                 "MTRR snapshot: MTRRCAP={:#018x}, DEF_TYPE={:#018x}, enabled={}, fixed-enabled={}, fixed-supported={}, WC-supported={}, variable-pairs={}",
656:                 registers.capability,
657:                 registers.default_type,
658:                 registers.default_type & (1 << 11) != 0,
659:                 registers.default_type & (1 << 10) != 0,
660:                 registers.capability & (1 << 8) != 0,
661:                 registers.capability & (1 << 10) != 0,
662:                 registers.variable_register_count
663:             )
664:         }
665:     }
666:     match (&cpu.mtrr, cpu.pat_msr_value, cpu.physical_address_bits) {
667:         (MtrrState::Captured(registers), Some(pat_value), Some(address_bits)) => {
668:             match (
669:                 registers.validated_layout(address_bits),
670:                 PatLayout::from_msr_value(pat_value),
671:             ) {
672:                 (Ok(mtrr), Ok(pat)) => crate::kprintln!(
673:                     "MTRR/PAT: validated; effective type at PA 0x0 using PAT[0]={:?}",
674:                     mtrr.effective_memory_type_for(0, pat, 0, cpu.normal_caching)
675:                 ),
676:                 (Err(error), _) => {
677:                     crate::kprintln!("MTRR/PAT: rejected captured MTRR state: {:?}", error)
678:                 }
679:                 (_, Err(error)) => {
680:                     crate::kprintln!("MTRR/PAT: rejected captured PAT state: {:?}", error)
681:                 }
682:             }
683:         }
684:         _ => crate::kprintln!(
685:             "MTRR/PAT: effective type unavailable (missing state or address width)"
686:         ),
687:     }
688:     crate::kprintln!(
689:         "CPU address widths (bits): physical={:?}, max-linear={:?}, active-linear={} (LA57 active={})",
690:         cpu.physical_address_bits,
