651:     pub fn range_is_within_acpi_regions(
652:         &self,
653:         start: u64,
654:         end: u64,
655:         physical_address_bits: Option<u8>,
656:     ) -> bool {
657:         if start >= end
658:             || physical_address_bits
659:                 .is_some_and(|bits| !physical_range_fits_address_width(start, end, bits))
660:         {
661:             return false;
662:         }
663: 
664:         let mut covered_until = start;
665:         for region in self.regions() {
666:             if region.end <= covered_until {
667:                 continue;
668:             }
669:             if region.start > covered_until
670:                 || !matches!(
671:                     region.kind,
672:                     RegionKind::AcpiReclaimable | RegionKind::AcpiNvs
673:                 )
674:             {
675:                 return false;
676:             }
677:             covered_until = region.end.min(end);
678:             if covered_until == end {
679:                 return true;
680:             }
681:         }
682:         false
683:     }
