685:     /// Calculate the Limine base-revision-3 HHDM address of a page-aligned
686:     /// extent wholly contained in one region that Limine maps into the HHDM.
687:     ///
688:     /// This validates metadata and relies on the Limine handoff contract for the
689:     /// actual mapping; it does not inspect inherited page tables or make the
690:     /// returned integer safe to dereference by itself.
691:     pub fn limine_hhdm_address(
692:         &self,
693:         hhdm_offset: u64,
694:         physical_start: u64,
695:         length: u64,
696:         physical_address_bits: Option<u8>,
697:         virtual_address_bits: u8,
698:     ) -> Result<u64, HhdmAddressError> {
699:         const PAGE_SIZE: u64 = 4096;
700: 
701:         let physical_address_bits =
702:             physical_address_bits.ok_or(HhdmAddressError::UnknownPhysicalAddressWidth)?;
703:         if length == 0 {
704:             return Err(HhdmAddressError::EmptyRange);
705:         }
706:         if (physical_start | length) & (PAGE_SIZE - 1) != 0 {
707:             return Err(HhdmAddressError::UnalignedRange);
708:         }
709:         let physical_end = physical_start
710:             .checked_add(length)
711:             .ok_or(HhdmAddressError::AddressOverflow)?;
712:         if !self.regions().iter().any(|region| {
713:             region.start <= physical_start
714:                 && physical_end <= region.end
715:                 && region.kind.is_mapped_by_limine_v3_hhdm()
716:         }) {
717:             return Err(HhdmAddressError::NotLimineMapped);
718:         }
719:         if !limine_v3_hhdm_range_is_valid(
720:             hhdm_offset,
721:             physical_start,
722:             physical_end,
723:             Some(physical_address_bits),
724:             virtual_address_bits,
725:         ) {
726:             return Err(HhdmAddressError::InvalidHhdmRange);
727:         }
728:         hhdm_offset
729:             .checked_add(physical_start)
730:             .ok_or(HhdmAddressError::InvalidHhdmRange)
731:     }
732: 
733:     /// Calculate the HHDM address of a page-aligned extent wholly contained in
734:     /// validated `Usable` memory.
735:     pub fn usable_hhdm_address(
736:         &self,
737:         hhdm_offset: u64,
738:         physical_start: u64,
739:         length: u64,
740:         physical_address_bits: Option<u8>,
741:         virtual_address_bits: u8,
742:     ) -> Result<u64, HhdmAddressError> {
743:         const PAGE_SIZE: u64 = 4096;
744: 
745:         if length == 0 {
746:             return Err(HhdmAddressError::EmptyRange);
747:         }
748:         if (physical_start | length) & (PAGE_SIZE - 1) != 0 {
749:             return Err(HhdmAddressError::UnalignedRange);
750:         }
751:         let physical_end = physical_start
752:             .checked_add(length)
753:             .ok_or(HhdmAddressError::AddressOverflow)?;
754:         if !self.range_is_within_region_kind(physical_start, physical_end, RegionKind::Usable) {
755:             return Err(HhdmAddressError::NotUsable);
756:         }
757:         self.limine_hhdm_address(
758:             hhdm_offset,
759:             physical_start,
760:             length,
761:             physical_address_bits,
762:             virtual_address_bits,
763:         )
764:     }
765: 
766:     pub const fn usable_bytes(&self) -> u64 {
767:         self.usable_bytes
768:     }
769: }
