771: /// Incremental validator used to copy loader entries without an intermediate heap.
772: pub struct MemoryMapBuilder {
773:     map: MemoryMap,
774: }
775: 
776: impl MemoryMapBuilder {
777:     pub const fn new() -> Self {
778:         Self {
779:             map: MemoryMap::EMPTY,
780:         }
781:     }
782: 
783:     pub fn push(&mut self, base: u64, length: u64, raw_kind: u64) -> Result<(), MemoryMapError> {
784:         let index = self.map.region_count;
785:         if index == MAX_MEMORY_REGIONS {
786:             return Err(MemoryMapError::TooManyRegions);
787:         }
788:         if length == 0 {
789:             return Err(MemoryMapError::EmptyRegion { index });
790:         }
791:         let end = base
792:             .checked_add(length)
793:             .ok_or(MemoryMapError::AddressOverflow { index })?;
794:         let kind = RegionKind::from_limine(raw_kind);
795: 
796:         for (other_index, other) in self.map.regions().iter().enumerate() {
797:             if base < other.end && other.start < end {
798:                 return Err(MemoryMapError::OverlappingRegions {
799:                     first: other_index,
800:                     second: index,
801:                 });
802:             }
803:         }
804: 
805:         let usable_bytes = if kind == RegionKind::Usable {
806:             self.map
807:                 .usable_bytes
808:                 .checked_add(length)
809:                 .ok_or(MemoryMapError::UsableTotalOverflow)?
810:         } else {
811:             self.map.usable_bytes
812:         };
813: 
814:         self.map.regions[index] = PhysicalRegion {
815:             start: base,
816:             end,
817:             kind,
818:         };
819:         self.map.region_count += 1;
820:         self.map.usable_bytes = usable_bytes;
821:         Ok(())
822:     }
823: 
824:     pub fn finish(self) -> Result<MemoryMap, MemoryMapError> {
825:         if self.map.region_count == 0 {
826:             Err(MemoryMapError::EmptyMap)
827:         } else {
828:             Ok(self.map)
829:         }
830:     }
831: }
832: 
833: impl Default for MemoryMapBuilder {
834:     fn default() -> Self {
835:         Self::new()
836:     }
837: }
838: 
839: /// Add an already-validated usable region length to a running total.
840: ///
841: /// Non-usable regions leave the total unchanged. `None` signals arithmetic
842: /// overflow so callers can report malformed or unrepresentable maps.
843: pub const fn add_usable_bytes(total: u64, region_kind: u64, region_length: u64) -> Option<u64> {
844:     if region_kind == MEMORY_MAP_USABLE {
845:         total.checked_add(region_length)
846:     } else {
847:         Some(total)
848:     }
849: }
